import { useQuery } from '@tanstack/react-query';
import { getProductPricesQueryOptions } from '@/query/options/products';
import { useI18n } from '@/hooks/useI18n';
import type { Plan, PlanCode } from '@/schema/api/products/prices';

/**
 * 가격 포맷팅 함수
 * @param price 가격 (정수)
 * @param currency 통화 코드
 * @returns 포맷팅된 가격 문자열 (예: "190,000원")
 */
export const formatPrice = (
  price: number,
  currency: 'KRW' | 'USD' = 'KRW'
): string => {
  if (currency === 'KRW') {
    return new Intl.NumberFormat('ko-KR').format(price) + '원';
  }
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  }).format(price);
};

/** 포맷팅된 가격이 포함된 플랜 정보 */
export type PlanWithDisplayPrice = Plan & {
  currency: 'KRW' | 'USD';
  displayMonthlyPrice: string;
  displayTotalPrice: string;
};

/**
 * 플랜 가격 정보 조회 훅
 *
 * @example
 * ```tsx
 * const { plans, getPlan, isLoading } = useProductPrices();
 *
 * // 전체 플랜 정보
 * plans?.forEach(plan => console.log(plan.displayName));
 *
 * // 특정 플랜 정보
 * const plan = getPlan('PASS_3M');
 * console.log(plan?.displayMonthlyPrice); // "116,000원"
 * console.log(plan?.displayTotalPrice);   // "350,000원"
 * ```
 */
export const useProductPrices = () => {
  const { currentLanguage } = useI18n([]);
  const { data, isLoading, error } = useQuery(getProductPricesQueryOptions());

  const plans = data?.data.plans;
  const currency: 'KRW' | 'USD' = currentLanguage === 'ko' ? 'KRW' : 'USD';

  const getPlan = (planCode: PlanCode): PlanWithDisplayPrice | undefined => {
    if (!plans) return undefined;

    const plan = plans.find((p) => p.planCode === planCode);
    if (!plan) return undefined;

    const priceData = plan.prices[currency];

    return {
      ...plan,
      totalAmount: priceData.totalAmount,
      monthlyEquivalentAmount: priceData.monthlyEquivalentAmount,
      currency,
      displayMonthlyPrice: formatPrice(priceData.monthlyEquivalentAmount, currency),
      displayTotalPrice: formatPrice(priceData.totalAmount, currency)
    };
  };

  return {
    plans,
    getPlan,
    currency,
    isLoading,
    error
  };
};
