import { useQuery } from '@tanstack/react-query';
import { getSubscriptionQueryOptions } from '@/query/options/subscription';

export const useCanPurchasePass = () => {
  const { data: subscriptionData, isLoading } = useQuery(
    getSubscriptionQueryOptions()
  );

  const hasActivePlan = Boolean(subscriptionData?.data);

  return {
    canPurchasePass: !isLoading && !hasActivePlan,
    hasActivePlan,
    isLoading
  };
};
