import { getReferralValidate } from '@/api/referral';
import { postTossOrder } from '@/api/tossPayments';
import type { TossOrderData } from '@/schema/api/payments/toss';
import type { PlanCode } from '@/schema/api/products/prices';

export interface PreparedPassOrder {
  orderData: TossOrderData;
  hasValidReferralCode: boolean;
  referrerName: string | null;
}

interface PreparePassOrderParams {
  planCode: PlanCode;
  couponCode?: string;
}

export const preparePassOrder = async ({
  planCode,
  couponCode
}: PreparePassOrderParams): Promise<PreparedPassOrder> => {
  let validReferralCode: string | undefined;
  let hasValidReferralCode = false;
  let referrerName: string | null = null;

  const storedRef = localStorage.getItem('referralCode');

  if (storedRef) {
    try {
      const result = await getReferralValidate(storedRef);

      if (result.valid) {
        validReferralCode = storedRef;
        hasValidReferralCode = true;
        referrerName = result.referrerDisplayName ?? null;
      } else {
        localStorage.removeItem('referralCode');
      }
    } catch (error) {
      console.error('Referral validation failed:', error);
    }
  }

  const response = await postTossOrder({
    planCode,
    couponCode: couponCode?.trim() || undefined,
    referralCode: validReferralCode,
    currency: 'KRW'
  });

  if (response.error) {
    throw new Error(response.error.message || '주문 생성에 실패했습니다.');
  }

  return {
    orderData: response.data,
    hasValidReferralCode,
    referrerName
  };
};
