import { useState, type ChangeEvent } from 'react';
import { Check } from 'lucide-react';
import { useTheme } from '@emotion/react';
import { useQueryClient } from '@tanstack/react-query';
import { Button, Flex, Input, Spinner } from '@docs-front/ui';
import { Coupon } from '@docs-front/ui';
import { postPaymentDocsCoupon } from '@/api/payments';
import { useI18n } from '@/hooks/useI18n';
import { useBreakPoints } from '@/hooks/useBreakPoints';
import { formatPrice, useProductPrices } from '@/hooks/useProductPrices';
import { getAccountMeQueryOptions } from '@/query/options/account';
import type { Plan, PlanCode } from '@/schema/api/products/prices';
import { TossPaymentModal } from '@/routes/_authenticated/credit-plan/-components/TossPaymentModal/TossPaymentModal';
import {
  preparePassOrder,
  type PreparedPassOrder
} from '@/routes/_authenticated/credit-plan/-components/TossPaymentModal/preparePassOrder';
import {
  StyledPricingPlanCard,
  StyledPricingPlanCardBackground,
  StyledPricingPlanCardCheckbox,
  StyledPricingPlanCardHeaderSection,
  StyledPricingPlanCardTitle,
  StyledCouponText
} from '@/routes/_authenticated/credit-plan/-components/PricingPlanModal/PricingPlanModal.style';
import {
  StyledPlanPriceRow,
  StyledPlanPriceLabel,
  StyledPlanMonthlyPrice,
  StyledPlanMonthlyUnit,
  StyledPlanTotalPrice,
  StyledPlanMostPopularBadge,
  StyledPlanDiscountBadge,
  StyledPlanSubInfo,
  StyledPlanCardWrapper,
  StyledCouponErrorText,
  StyledCouponSuccessText
} from '@/routes/_authenticated/credit-plan/-components/PricingPlanModal/PlanCard.style';

interface PlanCardProps {
  plan: Plan;
  isMostPopular?: boolean;
}

export const PlanCard = ({ plan, isMostPopular }: PlanCardProps) => {
  const theme = useTheme();
  const queryClient = useQueryClient();
  const { t } = useI18n(['pricing']);
  const { sm } = useBreakPoints();
  const { currency } = useProductPrices();
  const [coupon, setCoupon] = useState('');
  const [isTossModalOpen, setIsTossModalOpen] = useState(false);
  const [couponError, setCouponError] = useState<string | null>(null);
  const [couponSuccessMessage, setCouponSuccessMessage] = useState<string | null>(null);
  const [isPreparingCheckout, setIsPreparingCheckout] = useState(false);
  const [prefetchedOrder, setPrefetchedOrder] = useState<PreparedPassOrder | null>(null);

  const priceData = plan.prices[currency];
  const planKey = plan.planCode as PlanCode;

  const title = t(`pricing:plan.${planKey}.title`);
  const buttonText = t(`pricing:plan.${planKey}.buttonText`);
  const translatedFeatures = t(`pricing:plan.${planKey}.features`, {
    returnObjects: true
  });
  const features = Array.isArray(translatedFeatures) ? translatedFeatures : [];
  const discountBadge = t(`pricing:plan.${planKey}.discountBadge`, { defaultValue: '' });
  const localCouponAppliedMessage = t('pricing:ui.card.localCouponApplied');
  const couponRetryMessage = t('pricing:ui.card.couponCheckRetry');

  // 1개월권은 "월", 3/12개월권은 "월 환산"
  const priceLabel = plan.durationMonths === 1
    ? t('pricing:plan.priceLabel')
    : t('pricing:plan.priceConvertedLabel');

  const subInfo = t('pricing:plan.immediateAccess');

  const handleCouponChange = (e: ChangeEvent<HTMLInputElement>) => {
    setCoupon(e?.target?.value ?? '');
    setCouponError(null);
    setCouponSuccessMessage(null);
    setPrefetchedOrder(null);
  };

  const handleTossModalChange = (open: boolean) => {
    setIsTossModalOpen(open);

    if (!open) {
      setPrefetchedOrder(null);
    }
  };

  const resolveCouponBeforeCheckout = async (
    trimmedCoupon: string
  ): Promise<PreparedPassOrder | null> => {
    const localCouponResult = await postPaymentDocsCoupon(trimmedCoupon);

    if (localCouponResult.status === 'applied') {
      await Promise.all([
        queryClient.invalidateQueries({
          queryKey: getAccountMeQueryOptions().queryKey
        }),
        queryClient.invalidateQueries({
          queryKey: ['payment', 'history']
        })
      ]);

      setCoupon('');
      setPrefetchedOrder(null);
      setCouponSuccessMessage(localCouponAppliedMessage);

      return null;
    }

    if (localCouponResult.status === 'invalid') {
      throw new Error(localCouponResult.message ?? '');
    }

    return await preparePassOrder({
      planCode: planKey,
      couponCode: trimmedCoupon
    });
  };

  const handleCheckout = async () => {
    const trimmedCoupon = coupon.trim();

    setCouponError(null);
    setCouponSuccessMessage(null);

    if (!trimmedCoupon) {
      setPrefetchedOrder(null);
      setIsTossModalOpen(true);
      return;
    }

    setIsPreparingCheckout(true);

    try {
      const preparedOrder = await resolveCouponBeforeCheckout(trimmedCoupon);

      if (!preparedOrder) {
        return;
      }

      setPrefetchedOrder(preparedOrder);
      setIsTossModalOpen(true);
    } catch (error) {
      const message =
        error instanceof Error && error.message
          ? error.message
          : couponRetryMessage;
      setCouponError(message);
    } finally {
      setIsPreparingCheckout(false);
    }
  };

  return (
    <>
      <StyledPlanCardWrapper>
        {isMostPopular && (
          <StyledPlanMostPopularBadge>
            {t('pricing:plan.mostPopular')}
          </StyledPlanMostPopularBadge>
        )}
        <StyledPricingPlanCard
          borderColor={isMostPopular ? theme.color.main : theme.color.borderGray}
          borderWidth="1px"
          isRecommended={false}
          $isSm={sm}
        >
          <StyledPricingPlanCardBackground background={theme.color.white}>
            <Flex direction="column" gap={12} alignSelf="stretch">
              <StyledPricingPlanCardHeaderSection>
                <Flex height={22} alignItems="center" gap={8} alignSelf="stretch">
                  <StyledPricingPlanCardTitle>
                    {title}
                  </StyledPricingPlanCardTitle>
                  {discountBadge && (
                    <StyledPlanDiscountBadge>{discountBadge}</StyledPlanDiscountBadge>
                  )}
                </Flex>

                <StyledPlanPriceRow>
                  <StyledPlanPriceLabel>{priceLabel}</StyledPlanPriceLabel>
                  <Flex alignItems="flex-end" gap={2}>
                    <StyledPlanMonthlyPrice $isMobile={sm}>
                      {formatPrice(priceData.monthlyEquivalentAmount, currency)}
                    </StyledPlanMonthlyPrice>
                    <StyledPlanMonthlyUnit>
                      {currency === 'KRW' ? '원/월' : '/mo'}
                    </StyledPlanMonthlyUnit>
                  </Flex>
                  <StyledPlanTotalPrice>
                    {t('pricing:plan.totalPayment')} {formatPrice(priceData.totalAmount, currency)}
                  </StyledPlanTotalPrice>
                </StyledPlanPriceRow>
              </StyledPricingPlanCardHeaderSection>

              <Flex
                direction="column"
                gap={12}
                alignSelf="stretch"
                padding="0px 24px 24px 24px"
              >
                {/* 쿠폰 입력 */}
                <Flex alignItems="start" direction="column" gap={8}>
                  <StyledCouponText>
                    <Coupon />
                    {t('pricing:ui.card.haveCouponCode')}
                  </StyledCouponText>
                  <Flex alignItems="center" gap={8}>
                    <Input
                      placeholder={t('pricing:ui.card.enterCouponCode')}
                      style={{ fontSize: 15 }}
                      width="100%"
                      height={40}
                      value={coupon}
                      onChange={handleCouponChange}
                    />
                    <Button
                      variant="filled"
                      size="medium"
                      disabled={!coupon?.trim() || isPreparingCheckout}
                      onClick={handleCheckout}
                      style={{ whiteSpace: 'nowrap' }}
                    >
                      {isPreparingCheckout ? (
                        <Flex alignItems="center" gap={8}>
                          <Spinner size={16} />
                          확인 중...
                        </Flex>
                      ) : (
                        t('pricing:ui.card.getStartedWithDiscount')
                      )}
                    </Button>
                  </Flex>
                  {couponError && <StyledCouponErrorText>{couponError}</StyledCouponErrorText>}
                  {couponSuccessMessage && (
                    <StyledCouponSuccessText>{couponSuccessMessage}</StyledCouponSuccessText>
                  )}
                </Flex>

                {/* CTA 버튼 */}
                <Button
                  variant={isMostPopular ? 'filled' : 'outlined'}
                  size="medium"
                  width="100%"
                  style={{
                    boxSizing: 'border-box',
                    ...(isMostPopular
                      ? {}
                      : { backgroundColor: theme.color.bgBlueGray, color: theme.color.black })
                  }}
                  disabled={isPreparingCheckout}
                  onClick={handleCheckout}
                >
                  {isPreparingCheckout ? (
                    <Flex alignItems="center" gap={8}>
                      <Spinner size={16} />
                      확인 중...
                    </Flex>
                  ) : (
                    buttonText
                  )}
                </Button>

                {/* 부가 정보 */}
                <StyledPlanSubInfo>{subInfo}</StyledPlanSubInfo>

                {/* Features */}
                <Flex direction="column" gap={12} alignSelf="stretch">
                  {features.map((feature) => (
                    <Flex key={feature} alignItems="center" gap={12}>
                      <StyledPricingPlanCardCheckbox>
                        <Check size={16} color={theme.color.main} />
                      </StyledPricingPlanCardCheckbox>
                      <p style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{feature}</p>
                    </Flex>
                  ))}
                </Flex>
              </Flex>
            </Flex>
          </StyledPricingPlanCardBackground>
        </StyledPricingPlanCard>
      </StyledPlanCardWrapper>

      <TossPaymentModal
        open={isTossModalOpen}
        onOpenChange={handleTossModalChange}
        planCode={planKey}
        displayName={plan.displayName}
        couponCode={coupon}
        prefetchedOrder={prefetchedOrder}
      />
    </>
  );
};
